function kff_out($code, $data) { http_response_code($code); echo json_encode($data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE); exit; }
function kff_fail($code, $msg) { kff_out($code, ['ok' => false, 'error' => $msg]); }
